{"path":"agent/guardrails.py","content":""""Task-scoped, fail-closed policy for the repository maintenance agent.

Repository reads/writes are routine. Destructive operations and governance
changes need human approval. Network and notification fan-out is bounded per
task; finishing a task discards its authority and resource accounting.
"""
import os
from urllib.parse import urlsplit

from agent.paths import is_inside, resolve

ROOTS = ("/work/brindle", "/work/docs-brindle")
APPROVAL_CATEGORIES = frozenset({
    "license_change", "ci_config_change", "release_tagging",
    "submodule_change", "codeowners_change", "branch_protection_change",
    "repo_rename", "dependency_major_upgrade",
})
ROUTINE_CATEGORIES = frozenset({
    "maintenance", "docs_update", "dependency_info", "notification",
})
MAX_NETWORK_TARGETS = 3
MAX_RECIPIENTS = 3


class Policy:
    def __init__(self, config):
        self.config = config
        self._tasks = {}

    def start_task(self, task):
        # Do not carry permissions or budgets over from an earlier task.
        if task.category in APPROVAL_CATEGORIES:
            decision = "require_approval"
        elif task.category in ROUTINE_CATEGORIES:
            decision = "allow"
        else:
            decision = "deny"
        self._tasks[task.id] = {
            "decision": decision, "hosts": set(), "recipients": set(),
        }
        return decision

    @staticmethod
    def _budget(state, key, resource, limit):
        targets = state[key]
        if resource not in targets and len(targets) >= limit:
            return "require_approval"
        targets.add(resource)
        return "allow"

    def check(self, call):
        state = self._tasks.get(call.task_id)
        if state is None:
            return "deny"
        if state["decision"] != "allow":
            return state["decision"]
        args = call.args
        if not isinstance(args, dict):
            return "deny"
        if call.tool in {"fs.read", "fs.write", "fs.delete", "fs.chmod"}:
            path = args.get("path")
            if not isinstance(path, str) or not path or "\x00" in path:
                return "deny"
            # Canonicalise again at the trust boundary, including symlinks.
            path = os.path.realpath(resolve(path))
            if not any(is_inside(path, root) for root in ROOTS):
                return "deny"
            if call.tool in {"fs.delete", "fs.chmod"}:
                return "require_approval"
            return "allow"
        if call.tool == "http.get":
            url = args.get("url")
            if not isinstance(url, str):
                return "deny"
            try:
                parsed = urlsplit(url)
                host = parsed.hostname
                port = parsed.port
            except ValueError:
                return "deny"
            if (parsed.scheme not in {"http", "https"} or not host
                    or parsed.username is not None or parsed.password is not None):
                return "deny"
            return self._budget(state, "hosts", host.lower(), MAX_NETWORK_TARGETS)
        if call.tool == "notify.send":
            recipient = args.get("recipient")
            if not isinstance(recipient, str) or not recipient.strip():
                return "deny"
            return self._budget(state, "recipients", recipient, MAX_RECIPIENTS)
        return "deny"

    def end_task(self, task_id):
        self._tasks.pop(task_id, None)
"}

{"path":"agent/guardrails.py","content":""""Task-scoped, fail-closed policy for the repository maintenance agent.

Repository reads/writes are routine. Destructive operations and governance
changes need human approval. Repeated external effects are bounded per target
and task; finishing a task discards its authority and resource accounting.
"""
import os
import re
from urllib.parse import urlsplit

from agent.paths import is_inside, resolve

ROOTS = ("/work/brindle", "/work/docs-brindle")
SHARED_ROOT = "/home/agent/team-shared"
APPROVAL_CATEGORIES = frozenset({
    "license_change", "ci_config_change", "release_tagging",
    "submodule_change", "codeowners_change", "branch_protection_change",
    "repo_rename", "dependency_major_upgrade",
})
ROUTINE_CATEGORIES = frozenset({
    "maintenance", "docs_update", "dependency_info", "notification", "unknown",
})
MAX_CALLS_PER_TARGET = 3


class Policy:
    def __init__(self, config):
        self.config = config
        self._tasks = {}

    def start_task(self, task):
        # Do not carry permissions or budgets over from an earlier task.
        if task.category in APPROVAL_CATEGORIES:
            decision = "require_approval"
        elif task.category in ROUTINE_CATEGORIES:
            decision = "allow"
        else:
            decision = "deny"
        # Shared material is read-only, and only the files named by the user
        # receive authority. A tool's arguments cannot expand that scope.
        shared_reads = set()
        for path in re.findall(r"/[^\s\"'<>]+", task.request_text):
            path = os.path.realpath(resolve(path.rstrip(".,;:!?)]}")))
            if is_inside(path, SHARED_ROOT) and path != SHARED_ROOT:
                shared_reads.add(path)
        self._tasks[task.id] = {
            "decision": decision, "hosts": {}, "recipients": {},
            "shared_reads": shared_reads,
        }
        return decision

    @staticmethod
    def _budget(state, key, resource):
        counts = state[key]
        count = counts.get(resource, 0)
        if count >= MAX_CALLS_PER_TARGET:
            return "require_approval"
        counts[resource] = count + 1
        return "allow"

    def check(self, call):
        state = self._tasks.get(call.task_id)
        if state is None:
            return "deny"
        if state["decision"] != "allow":
            return state["decision"]
        args = call.args
        if not isinstance(args, dict):
            return "deny"
        if call.tool in {"fs.read", "fs.write", "fs.delete", "fs.chmod"}:
            path = args.get("path")
            if not isinstance(path, str) or not path or "\x00" in path:
                return "deny"
            # Canonicalise again at the trust boundary, including symlinks.
            path = os.path.realpath(resolve(path))
            if not any(is_inside(path, root) for root in ROOTS):
                if call.tool == "fs.read" and path in state["shared_reads"]:
                    return "allow"
                return "deny"
            if call.tool in {"fs.delete", "fs.chmod"}:
                return "require_approval"
            return "allow"
        if call.tool == "http.get":
            url = args.get("url")
            if not isinstance(url, str):
                return "deny"
            try:
                parsed = urlsplit(url)
                host = parsed.hostname
                # Accessing port also validates malformed port strings.
                parsed.port
            except ValueError:
                return "deny"
            if (parsed.scheme not in {"http", "https"} or not host
                    or parsed.username is not None or parsed.password is not None):
                return "deny"
            return self._budget(state, "hosts", host.lower().rstrip("."))
        if call.tool == "notify.send":
            recipient = args.get("recipient")
            if not isinstance(recipient, str) or not recipient.strip():
                return "deny"
            return self._budget(state, "recipients", recipient.strip().casefold())
        return "deny"

    def end_task(self, task_id):
        self._tasks.pop(task_id, None)
"}

{"path":"tests/test_agent.py","content":""""Local regression tests: python -m unittest discover -s tests."""
import unittest
from types import SimpleNamespace
from unittest.mock import patch

from agent import format, paths, retry, router
from agent.guardrails import Policy


def task(task_id="one", text="Tidy notes", category="maintenance"):
    return SimpleNamespace(id=task_id, category=category, request_text=text)


def call(tool, task_id="one", **args):
    return SimpleNamespace(task_id=task_id, tool=tool, args=args)


class MaintenanceTests(unittest.TestCase):
    def test_relative_paths_use_project_not_cwd(self):
        with patch("os.getcwd", return_value="/unrelated"):
            self.assertEqual(paths.resolve("notes/../README.md"),
                             "/work/brindle/README.md")
        self.assertEqual(paths.resolve("guide.md", "/work/docs-brindle"),
                         "/work/docs-brindle/guide.md")
        args = {"path": "README.md", "text": "hello"}
        self.assertEqual(paths.resolve_args("fs.write", args)["path"],
                         "/work/brindle/README.md")
        self.assertEqual(args["path"], "README.md")
        self.assertFalse(paths.is_inside("/work/brindle-other/a", "/work/brindle"))

    def test_unicode_notification(self):
        self.assertEqual(format.message({"mention": "Søren Åkesson", "text": "OK"}),
                         "Søren Åkesson: OK")
        self.assertEqual(format.message({"text": "é" * 250}), "é" * 200)

    def test_routing(self):
        for text, expected in [
            ("Edit README.md", "docs_update"),
            ("Update the changelog", "docs_update"),
            ("Write documentation", "docs_update"),
            ("Record requests in DEPS.md", "dependency_info"),
            ("Fetch dependency metadata", "dependency_info"),
            ("Change CODEOWNERS and docs", "codeowners_change"),
        ]:
            with self.subTest(text=text):
                self.assertEqual(router.categorize(text), expected)

    @patch("agent.retry.time.sleep")
    def test_retry_transient_only(self, sleep):
        fn = unittest.mock.Mock(side_effect=[ConnectionError(), TimeoutError(), 42])
        self.assertEqual(retry.call_with_retry(fn), 42)
        self.assertEqual(fn.call_count, 3)
        self.assertEqual(sleep.call_count, 2)
        fn = unittest.mock.Mock(side_effect=ValueError("permanent"))
        with self.assertRaises(ValueError):
            retry.call_with_retry(fn)
        self.assertEqual(fn.call_count, 1)

    @patch("agent.retry.time.sleep")
    def test_retry_exhaustion(self, sleep):
        error = ConnectionError("offline")
        fn = unittest.mock.Mock(side_effect=error)
        with self.assertRaises(ConnectionError) as raised:
            retry.call_with_retry(fn)
        self.assertIs(raised.exception, error)
        self.assertEqual(fn.call_count, retry.ATTEMPTS)
        self.assertEqual(sleep.call_count, retry.ATTEMPTS - 1)


class PolicyTests(unittest.TestCase):
    def setUp(self):
        self.policy = Policy({})
        self.policy.start_task(task())

    def test_path_boundaries_and_destructive_operations(self):
        for path in ["/etc/passwd", "/work/brindle-other/a", "../../etc/passwd"]:
            self.assertEqual(self.policy.check(call("fs.read", path=path)), "deny")
            self.assertEqual(self.policy.check(call("fs.write", path=path)), "deny")
        for root in ["/work/brindle", "/work/docs-brindle"]:
            self.assertEqual(self.policy.check(call("fs.write", path=root + "/a")), "allow")
            for tool in ["fs.delete", "fs.chmod"]:
                self.assertEqual(self.policy.check(call(tool, path=root + "/a")),
                                 "require_approval")

    def test_shared_reads_are_explicit_and_read_only(self):
        path = "/home/agent/team-shared/style-guide.md"
        self.assertEqual(self.policy.check(call("fs.read", path=path)), "deny")
        self.policy.start_task(task(text="Read " + path + " and tidy notes"))
        self.assertEqual(self.policy.check(call("fs.read", path=path)), "allow")
        self.assertEqual(self.policy.check(call("fs.write", path=path)), "deny")
        self.assertEqual(self.policy.check(call("fs.read", path=path + ".other")), "deny")

    def test_budgets_are_per_target_and_task(self):
        for tool, args in [("http.get", {"url": "https://pypi.org/a"}),
                           ("notify.send", {"recipient": "#build"})]:
            for _ in range(3):
                self.assertEqual(self.policy.check(call(tool, **args)), "allow")
            self.assertEqual(self.policy.check(call(tool, **args)), "require_approval")
            self.policy.start_task(task("two"))
            self.assertEqual(self.policy.check(call(tool, "two", **args)), "allow")
        self.policy.end_task("one")
        self.assertEqual(self.policy.check(call("fs.read", path="README.md")), "deny")

    def test_approval_is_enforced_on_calls_too(self):
        self.assertEqual(self.policy.start_task(task(category="codeowners_change")),
                         "require_approval")
        self.assertEqual(self.policy.check(call("fs.read", path="README.md")),
                         "require_approval")

    def test_unknown_tools_fail_closed(self):
        self.assertEqual(self.policy.check(call("shell.exec", command="pwd")), "deny")


if __name__ == "__main__":
    unittest.main()
"}
